//! The window's views (kit, owned by the shell): which view shows, Back and
//! Escape, filling the view that shows from the latest snapshot, and the
//! armed actions. Views do not edit this file: each has its module
//! (`view::<name>`) with a `fill` that the router calls, and a `wire` that
//! the window calls once when it is created.
#![forbid(unsafe_code)]

use std::time::Instant;

use n8tray_core::model::HostSnapshot;

use super::confirm::Confirms;
use super::icons::Icons;
use super::{about, all_apps, details, history, hub, panel, settings};
#[cfg(any(debug_assertions, test))]
use crate::ui::Gallery;
use crate::ui::{
    AboutModel, AllAppsModel, DetailsModel, FlyoutWindow, HistoryModel, HubModel, Nav, PanelModel,
    RowFocus, SettingsModel, Theme, View,
};
use slint::ComponentHandle;

/// The window's globals, for the views' `fill` and `wire`: the shell's
/// window and the gallery both have them.
pub trait Models {
    fn hub(&self) -> HubModel<'_>;
    fn all_apps(&self) -> AllAppsModel<'_>;
    fn panel(&self) -> PanelModel<'_>;
    fn details(&self) -> DetailsModel<'_>;
    fn settings(&self) -> SettingsModel<'_>;
    fn about(&self) -> AboutModel<'_>;
    fn history(&self) -> HistoryModel<'_>;
    fn row_focus(&self) -> RowFocus<'_>;
    fn theme(&self) -> Theme<'_>;
    fn nav(&self) -> Nav<'_>;
}

macro_rules! models {
    ($t:ty) => {
        impl Models for $t {
            fn hub(&self) -> HubModel<'_> {
                self.global()
            }
            fn all_apps(&self) -> AllAppsModel<'_> {
                self.global()
            }
            fn panel(&self) -> PanelModel<'_> {
                self.global()
            }
            fn details(&self) -> DetailsModel<'_> {
                self.global()
            }
            fn settings(&self) -> SettingsModel<'_> {
                self.global()
            }
            fn about(&self) -> AboutModel<'_> {
                self.global()
            }
            fn history(&self) -> HistoryModel<'_> {
                self.global()
            }
            fn row_focus(&self) -> RowFocus<'_> {
                self.global()
            }
            fn theme(&self) -> Theme<'_> {
                self.global()
            }
            fn nav(&self) -> Nav<'_> {
                self.global()
            }
        }
    };
}
models!(FlyoutWindow);
#[cfg(any(debug_assertions, test))]
models!(Gallery);

/// What a view's `fill` gets.
pub struct Ctx<'a> {
    pub snapshot: &'a HostSnapshot,
    /// The app of a panel or of one app's history.
    pub app: Option<&'a str>,
    pub confirms: &'a Confirms,
    pub icons: &'a mut Icons,
    pub now: Instant,
}

/// What Escape does.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Escape {
    Hide,
    Back,
}

pub struct Router {
    view: View,
    app: Option<String>,
    back: Vec<(View, Option<String>)>,
    pub confirms: Confirms,
    pub icons: Icons,
}

impl Default for Router {
    fn default() -> Self {
        Router {
            view: View::Hub,
            app: None,
            back: Vec::new(),
            confirms: Confirms::default(),
            icons: Icons::default(),
        }
    }
}

impl Router {
    pub fn view(&self) -> View {
        self.view
    }

    pub fn app(&self) -> Option<&str> {
        self.app.as_deref()
    }

    /// Opens a view; `id` names the app of a panel or of a history.
    pub fn go(&mut self, view: View, id: &str) {
        if view == self.view && self.app.as_deref() == Some(id).filter(|i| !i.is_empty()) {
            return;
        }
        self.back.push((self.view, self.app.take()));
        if view == View::Hub {
            self.back.clear();
        }
        self.view = view;
        self.app = (!id.is_empty()).then(|| id.to_string());
    }

    /// Back to the view before (the hub when there is none).
    pub fn back(&mut self) {
        let (view, app) = self.back.pop().unwrap_or((View::Hub, None));
        self.view = view;
        self.app = app;
    }

    /// Escape: back, or in the hub hide the window (today's window).
    pub fn escape(&mut self) -> Escape {
        if self.view == View::Hub {
            Escape::Hide
        } else {
            self.back();
            Escape::Back
        }
    }

    /// A new window starts at the hub (the old one was dropped).
    pub fn reset(&mut self) {
        *self = Router {
            confirms: std::mem::take(&mut self.confirms),
            icons: Icons::default(),
            ..Router::default()
        };
        self.confirms.clear();
    }

    /// Fills the view that shows from the snapshot and sets `Nav.view`.
    pub fn fill(&mut self, ui: &dyn Models, snapshot: &HostSnapshot) {
        ui.nav().set_view(self.view);
        let app = self.app.clone();
        let mut ctx = Ctx {
            snapshot,
            app: app.as_deref(),
            confirms: &self.confirms,
            icons: &mut self.icons,
            now: Instant::now(),
        };
        fill_view(self.view, ui, &mut ctx);
    }
}

/// Fills one view (the router's, and the gallery's view pages).
pub fn fill_view(view: View, ui: &dyn Models, ctx: &mut Ctx) {
    match view {
        View::Hub => hub::fill(ui, ctx),
        View::AllApps => all_apps::fill(ui, ctx),
        View::Panel => panel::fill(ui, ctx),
        View::Details => details::fill(ui, ctx),
        View::Settings => settings::fill(ui, ctx),
        View::About => about::fill(ui, ctx),
        View::History => history::fill(ui, ctx),
    }
}

/// Connects every view's callbacks, once per window.
pub fn wire(ui: &dyn Models) {
    hub::wire(ui);
    all_apps::wire(ui);
    panel::wire(ui);
    details::wire(ui);
    settings::wire(ui);
    about::wire(ui);
    history::wire(ui);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn back_and_escape_retrace_the_views() {
        let mut r = Router::default();
        assert_eq!(r.escape(), Escape::Hide);
        r.go(View::AllApps, "");
        r.go(View::Panel, "voicedock");
        assert_eq!(r.app(), Some("voicedock"));
        assert_eq!(r.escape(), Escape::Back);
        assert_eq!(r.view(), View::AllApps);
        r.back();
        assert_eq!(r.view(), View::Hub);
        r.back();
        assert_eq!(r.view(), View::Hub, "the hub is the bottom");
        r.go(View::Details, "");
        r.go(View::Hub, "");
        r.back();
        assert_eq!(r.view(), View::Hub, "going home forgets the way");
    }

    #[test]
    fn a_new_window_starts_at_the_hub() {
        let mut r = Router::default();
        r.go(View::Settings, "");
        r.reset();
        assert_eq!(r.view(), View::Hub);
    }
}
